#ifndef SERVICES_NETWORK_AEGIS_SHIELD_BLOCKLIST_H_
#define SERVICES_NETWORK_AEGIS_SHIELD_BLOCKLIST_H_

#include <cstddef>

namespace aegis {

// Sorted, de-duplicated, wildcard-free domain lists generated by
// aegis/shield/gen_blocklist.py (EasyList + EasyPrivacy network rules).
// A host is blocked when it equals an entry or is a subdomain of one.

extern const char* const kAegisBlockDomains[];
extern const size_t kAegisBlockDomainsCount;

// Exceptions (EasyList/EasyPrivacy @@ whitelist rules) plus the Aegis
// ecosystem and sync domains. Always checked before the blocklist.
extern const char* const kAegisAllowDomains[];
extern const size_t kAegisAllowDomainsCount;

}  // namespace aegis

#endif  // SERVICES_NETWORK_AEGIS_SHIELD_BLOCKLIST_H_
